void timeout_q_execute( Boolean execute , Timeout_Q_Obj *timeout_q_obj )
{    
    Timeout_Q_Status status ; 

    if( !execute ) return ;
    
    if( timeout_q_obj->timeout_q_func )
    {
        status = (timeout_q_obj->timeout_q_func)( timeout_q_obj->timeout_q_arg ) ;
        
        timeout_q_obj->req_done = !!(status&TIMEOUT_Q_COMPLETE);    		
    }
}

